int main() {
    int n;
    cin >> n;
    string input1,input2;
    cin >> input1;
    cin >> input2;
    // 统计第一个二进制数 1的数量 0 的数量
    long oneCount1, zeroCount;
    oneCount1 = zeroCount = 0;
    // 统计 第一个二进制 对应位为1 第二个二进制 为 0 的数量
    long diffCount1;
    // 统计 第一个二进制位0 第二个二进制也为0 的数量
    long diffCount0;
​
    diffCount1 = diffCount0 = 0;

    for (int i = 0; i < n; i++) {
        if (input1[i] == '1') {
            oneCount1++;
            if (input2[i] == '0') {
                diffCount1++;
            }
        } else {
            zeroCount++;
            if (input2[i] == '0') {
                diffCount0++;
            }
        }
    }

    long res = diffCount0 * oneCount1 + diffCount1 * zeroCount  - diffCount0 * diffCount1;
    cout << res;
    return 0;
}

