import java.util.Scanner;
​
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = Integer.parseInt(sc.nextLine());
        String input1 = sc.nextLine();
        String input2 = sc.nextLine();
        // 分别统计第一个二进制 0比特的数量 1比特的数量
        long oneCount1 = 0, zeroCount = 0;
        //  第一个为0 第二个为0 的数量
        long diffCount0 = 0;
        // 第一个为1 第二个为0的数量
        long diffCount1 = 0;
​
        for (int i = 0; i < n; i++) {
            if (input1.charAt(i) == '1') {
                oneCount1++;
                if (input2.charAt(i) == '0') {
                    diffCount1++;
                }
            } else {
                zeroCount++;
                if (input2.charAt(i) == '0') {
                    diffCount0++;
                }
            }
        }
​
        // 计算符合条件的组合数，减去重叠部分
        long res = diffCount0 * oneCount1 + diffCount1 * zeroCount - diffCount0 * diffCount1;
        System.out.println(res);
    }
}
