const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
​
rl.on('line', line => {
    lines.push(line.trim());
    if (lines.length === 3) rl.close();
});
​
rl.on('close', () => {
    const n = parseInt(lines[0]);
    const input1 = lines[1];
    const input2 = lines[2];
    // 分别统计第一个二进制 0比特的数量 1比特的数量
    let oneCount1 = 0n, zeroCount = 0n;
    // 第一个为0 第二个为0 的数量
    let diffCount0 = 0n;
    // 第一个为1 第二个为0的数量
    let diffCount1 = 0n;
​
    for (let i = 0; i < n; i++) {
        const a = input1[i], b = input2[i];
        if (a === '1') {
            oneCount1++;
            if (b === '0') diffCount1++;
        } else {
            zeroCount++;
            if (b === '0') diffCount0++;
        }
    }
​
