package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取第一行：n
    var n int
    fmt.Fscanln(reader, &n)
​
    // 读取第二行：input1
    input1Line, _ := reader.ReadString('\n')
    input1 := strings.TrimSpace(input1Line)
​
    // 读取第三行：input2
    input2Line, _ := reader.ReadString('\n')
    input2 := strings.TrimSpace(input2Line)
​
    // 分别统计第一个二进制 0比特的数量 1比特的数量
    var oneCount1, zeroCount int64
    // 第一个为0 第二个为0 的数量
    var diffCount0 int64
    // 第一个为1 第二个为0的数量
    var diffCount1 int64
​
    for i := 0; i < n; i++ {
        a := input1[i]
        b := input2[i]
​
        if a == '1' {
            oneCount1++
            if b == '0' {
                diffCount1++
            }
        } else {
            zeroCount++
            if b == '0' {
                diffCount0++
            }
        }
    }
​
    // 按照公式计算：去掉重复计算项
    res := diffCount0*oneCount1 + diffCount1*zeroCount - diffCount0*diffCount1
    fmt.Println(res)
}
